using System.Collections.ObjectModel;
using OpenFantasy.Core.Spatial;
using OpenFantasy.Core.Terrain;

namespace OpenFantasy.Hosting.Content.Cargo;

/// <summary>
/// Authored, finite corridor geometry joining the two retained merchant places. It is an L of full-size local
/// regions: the existing farm region, seven regions east along its rows and six regions south along the last
/// column, fourteen in all within the fixed sixteen-region local bound. Every added region is generated by the
/// basis region's own seed and stratified rules, so its support is the farm's ordinary flat ground. The corridor
/// is local qualification geometry, not procedural geography, streaming or town design. It overlays retained
/// source places in the same tile plane; each one is declared in <see cref="CargoCorridorOverlays"/> and checked.
/// </summary>
public sealed class CargoCorridor
{
    /// <summary>Cells between consecutive authored waypoints; each leg stays inside the fixed ground-search budget.</summary>
    public const int MaximumLegCells = 8;

    private const int EastwardRegions = 7;
    private const int SouthwardRegions = 6;

    private CargoCorridor(TerrainRegionBounds basis, IReadOnlyList<TerrainRegionBounds> added, CellCoordinate originApproach,
        CellCoordinate corner, CellCoordinate destinationApproach)
    {
        Basis = basis;
        AddedRegions = Array.AsReadOnly(added.ToArray());
        OriginApproach = originApproach;
        Corner = corner;
        DestinationApproach = destinationApproach;
        Outbound = Lane([originApproach, corner, destinationApproach]);
        Overlays = Array.AsReadOnly(Array.Empty<CargoPlaceOverlay>());
    }

    /// <summary>The checked retained places this corridor overlays, equal to the declared set.</summary>
    public IReadOnlyList<CargoPlaceOverlay> Overlays { get; private set; }

    /// <summary>The corner points of the authored lane; the homeward lane walks the same cells in reverse.</summary>
    public IReadOnlyList<CellCoordinate> LaneCorners => [OriginApproach, Corner, DestinationApproach];

    /// <summary>The retained farm region the corridor starts from; it is kept exactly.</summary>
    public TerrainRegionBounds Basis { get; }

    /// <summary>The authored regions added to the basis, in walking order.</summary>
    public ReadOnlyCollection<TerrainRegionBounds> AddedRegions { get; }

    /// <summary>Standing cell one diagonal step from the origin merchant's source tile.</summary>
    public CellCoordinate OriginApproach { get; }

    public CellCoordinate Corner { get; }

    /// <summary>Standing cell one diagonal step from the destination merchant's source tile.</summary>
    public CellCoordinate DestinationApproach { get; }

    /// <summary>Authored waypoints from the origin approach to the destination approach, at most eight cells apart.</summary>
    public ReadOnlyCollection<CellCoordinate> Outbound { get; }

    public IEnumerable<TerrainRegionBounds> AllRegions => AddedRegions.Prepend(Basis);

    /// <summary>
    /// Authors the circuit corridor around the actual farm region and the retained merchant tiles. Refuses when the
    /// basis is not the full-size region containing the origin tile, when the geometry would leave either tile,
    /// the walking lane or the region bound uncovered, or when a retained place it overlays is not declared exactly.
    /// </summary>
    public static CargoCorridor CreateCircuit(TerrainRegionBounds basis, CargoCircuitSources sources) =>
        CreateCircuit(basis, sources, CargoCorridorOverlays.Declared);

    internal static CargoCorridor CreateCircuit(TerrainRegionBounds basis, CargoCircuitSources sources,
        IReadOnlyList<CargoPlaceOverlay> declaredOverlays)
    {
        ArgumentNullException.ThrowIfNull(basis);
        ArgumentNullException.ThrowIfNull(sources);
        ArgumentNullException.ThrowIfNull(declaredOverlays);
        if (basis.Width != TerrainRegionBounds.MaximumWidth || basis.Depth != TerrainRegionBounds.MaximumDepth)
        {
            throw new InvalidDataException("The corridor extends one full-size basis region.");
        }
        List<TerrainRegionBounds> added = [];
        for (int east = 1; east <= EastwardRegions; east++)
        {
            added.Add(Region(basis, basis.Minimum.Offset((long)east * basis.Width, 0, 0)));
        }
        CellCoordinate cornerMinimum = added[^1].Minimum;
        for (int south = 1; south <= SouthwardRegions; south++)
        {
            added.Add(Region(basis, cornerMinimum.Offset(0, -(long)south * basis.Depth, 0)));
        }
        long surface = basis.Minimum.Z;
        CargoSourceMerchant origin = sources.Origin;
        CargoSourceMerchant destination = sources.Destination;
        var originApproach = new CellCoordinate(origin.TileX + 1, origin.TileY - 1, surface);
        var destinationApproach = new CellCoordinate(destination.TileX - 1, destination.TileY + 1, surface);
        var corner = new CellCoordinate(destinationApproach.X, originApproach.Y, surface);
        var corridor = new CargoCorridor(basis, added, originApproach, corner, destinationApproach);
        corridor.Validate(sources);
        IReadOnlyList<CargoPlaceOverlay> overlays = CargoCorridorOverlays.Compute(sources.Places, basis, added,
            corridor.LaneCorners);
        CargoCorridorOverlays.Check(overlays, declaredOverlays);
        corridor.Overlays = overlays;
        return corridor;
    }

    /// <summary>
    /// Generates the added regions from the basis region's own scope, seed and rules and returns them after every
    /// retained region, unchanged, so each retained cell, excavation and revision stays exact. Refuses when the
    /// basis is missing, an added region overlaps retained terrain or the total exceeds the fixed local bound.
    /// </summary>
    public IReadOnlyList<TerrainRegionSnapshot> GenerateTerrain(IReadOnlyList<TerrainRegionSnapshot> retained)
    {
        ArgumentNullException.ThrowIfNull(retained);
        TerrainRegionSnapshot basis = retained.SingleOrDefault(region => region.Bounds == Basis)
            ?? throw new ArgumentException("The corridor's basis is an exact retained region.", nameof(retained));
        if (retained.Count + AddedRegions.Count > LocalSpatialSnapshot.MaximumRegions)
        {
            throw new InvalidDataException("The retained regions and the corridor exceed the fixed local region bound.");
        }
        if (AddedRegions.Any(added => retained.Any(region => Overlaps(added, region.Bounds))))
        {
            throw new InvalidDataException("Corridor regions cannot overlap retained terrain.");
        }
        var generator = new StratifiedTerrainGenerator();
        return retained.Concat(AddedRegions.Select(bounds => generator.Generate(basis.Scope, basis.Seed, basis.Rules, bounds)))
            .ToArray();
    }

    /// <summary>Feet at the centre of a cell standing on its ground, the same transform the farm uses.</summary>
    public static SubunitPosition FeetAt(CellCoordinate cell) => new(
        checked(cell.X * SubunitPosition.SubunitsPerCell + SubunitPosition.SubunitsPerCell / 2),
        checked(cell.Y * SubunitPosition.SubunitsPerCell + SubunitPosition.SubunitsPerCell / 2),
        checked((cell.Z + 1) * SubunitPosition.SubunitsPerCell));

    /// <summary>The index of the corridor region containing a cell, or -1 outside the corridor.</summary>
    public int RegionIndexOf(CellCoordinate cell)
    {
        int index = 0;
        foreach (TerrainRegionBounds region in AllRegions)
        {
            if (region.Contains(cell)) return index;
            index++;
        }
        return -1;
    }

    private void Validate(CargoCircuitSources sources)
    {
        TerrainRegionBounds[] all = AllRegions.ToArray();
        if (all.Length > LocalSpatialSnapshot.MaximumRegions)
        {
            throw new InvalidDataException("The corridor exceeds the fixed local region bound.");
        }
        for (int index = 1; index < all.Length; index++)
        {
            if (!SharesFace(all[index - 1], all[index]))
            {
                throw new InvalidDataException("Consecutive corridor regions must share a full face.");
            }
        }
        var originTile = new CellCoordinate(sources.Origin.TileX, sources.Origin.TileY, Basis.Minimum.Z);
        var destinationTile = new CellCoordinate(sources.Destination.TileX, sources.Destination.TileY, Basis.Minimum.Z);
        CellCoordinate[] required = [originTile, destinationTile, .. Outbound];
        if (required.Any(cell => RegionIndexOf(cell) < 0))
        {
            throw new InvalidDataException("The corridor must cover both retained merchant tiles and every authored waypoint.");
        }
        if (!sources.Origin.Place.Contains(OriginApproach.X, OriginApproach.Y)
            || !sources.Destination.Place.Contains(DestinationApproach.X, DestinationApproach.Y))
        {
            throw new InvalidDataException("Each approach must stand inside its merchant's retained source place.");
        }
    }

    private static TerrainRegionBounds Region(TerrainRegionBounds basis, CellCoordinate minimum) =>
        new(minimum, basis.Width, basis.Depth, basis.Height);

    private static bool Overlaps(TerrainRegionBounds left, TerrainRegionBounds right) =>
        left.Minimum.X <= right.Maximum.X && left.Maximum.X >= right.Minimum.X
        && left.Minimum.Y <= right.Maximum.Y && left.Maximum.Y >= right.Minimum.Y
        && left.Minimum.Z <= right.Maximum.Z && left.Maximum.Z >= right.Minimum.Z;

    private static bool SharesFace(TerrainRegionBounds left, TerrainRegionBounds right) =>
        left.Minimum.Z == right.Minimum.Z && left.Height == right.Height
        && (left.Minimum.Y == right.Minimum.Y && left.Depth == right.Depth
                && (left.Maximum.X + 1 == right.Minimum.X || right.Maximum.X + 1 == left.Minimum.X)
            || left.Minimum.X == right.Minimum.X && left.Width == right.Width
                && (left.Maximum.Y + 1 == right.Minimum.Y || right.Maximum.Y + 1 == left.Minimum.Y));

    /// <summary>Authored waypoints along straight cardinal segments, at most eight cells apart, excluding the first corner.</summary>
    public static ReadOnlyCollection<CellCoordinate> Lane(IReadOnlyList<CellCoordinate> corners)
    {
        ArgumentNullException.ThrowIfNull(corners);
        return Array.AsReadOnly(Subdivide(corners).ToArray());
    }

    private static IEnumerable<CellCoordinate> Subdivide(IReadOnlyList<CellCoordinate> corners)
    {
        for (int index = 1; index < corners.Count; index++)
        {
            CellCoordinate from = corners[index - 1];
            CellCoordinate to = corners[index];
            long dx = Math.Sign(to.X - from.X);
            long dy = Math.Sign(to.Y - from.Y);
            if (dx != 0 && dy != 0)
            {
                throw new InvalidDataException("Authored corridor segments are cardinal.");
            }
            long length = Math.Abs(to.X - from.X) + Math.Abs(to.Y - from.Y);
            for (long travelled = MaximumLegCells; travelled < length; travelled += MaximumLegCells)
            {
                yield return from.Offset(dx * travelled, dy * travelled, 0);
            }
            yield return to;
        }
    }
}
